-- Seed: Document Review with Admin Triage workflow template
-- Flow: Upload -> Admin Triage -> (PASS -> Backoffice -> Reviewer) OR (APPROVED -> Reviewer) -> Approve/Reject

INSERT INTO ecm_workflow.workflow_templates (name, description, dsl_definition, bpmn_xml, bpmn_source, status, sla_hours)
VALUES (
  'Document Review with Triage',
  'Admin triages incoming documents to either Backoffice or Reviewer. Backoffice-routed docs go through an additional reviewer step.',
  '{"processKey":"doc-triage-review","name":"Document Review with Triage","steps":[],"endStates":[]}',
  E'<?xml version="1.0" encoding="UTF-8"?>\n<definitions xmlns="http://www.omg.org/spec/BPMN/20100524/MODEL"\n             xmlns:flowable="http://flowable.org/bpmn"\n             xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"\n             xmlns:omgdc="http://www.omg.org/spec/DD/20100524/DC"\n             xmlns:omgdi="http://www.omg.org/spec/DD/20100524/DI"\n             targetNamespace="http://www.flowable.org/processdef">\n  <process id="doc-triage-review" name="Document Review with Triage" isExecutable="true">\n    <startEvent id="start" name="Document Uploaded" flowable:initiator="initiator"/>\n    <sequenceFlow id="f1" sourceRef="start" targetRef="admin_triage"/>\n    <userTask id="admin_triage" name="Admin Triage" flowable:candidateGroups="ECM_ADMIN" flowable:formFieldValidation="false"/>\n    <sequenceFlow id="f2" sourceRef="admin_triage" targetRef="gw_route"/>\n    <exclusiveGateway id="gw_route" name="Route Decision"/>\n    <sequenceFlow id="f3_bo" sourceRef="gw_route" targetRef="backoffice_review">\n      <conditionExpression>${decision == \'PASS\'}</conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id="f3_rev" sourceRef="gw_route" targetRef="reviewer_review">\n      <conditionExpression>${decision == \'APPROVED\'}</conditionExpression>\n    </sequenceFlow>\n    <userTask id="backoffice_review" name="Backoffice Review" flowable:candidateGroups="ECM_BACKOFFICE" flowable:formFieldValidation="false"/>\n    <sequenceFlow id="f4" sourceRef="backoffice_review" targetRef="reviewer_review"/>\n    <userTask id="reviewer_review" name="Reviewer Final Review" flowable:candidateGroups="ECM_REVIEWER" flowable:formFieldValidation="false"/>\n    <sequenceFlow id="f5" sourceRef="reviewer_review" targetRef="gw_final"/>\n    <exclusiveGateway id="gw_final" name="Final Decision"/>\n    <sequenceFlow id="f6_approve" sourceRef="gw_final" targetRef="end_approved">\n      <conditionExpression>${decision == \'APPROVED\'}</conditionExpression>\n    </sequenceFlow>\n    <sequenceFlow id="f6_reject" sourceRef="gw_final" targetRef="end_rejected">\n      <conditionExpression>${decision == \'REJECTED\'}</conditionExpression>\n    </sequenceFlow>\n    <endEvent id="end_approved" name="Approved"/>\n    <endEvent id="end_rejected" name="Rejected"/>\n  </process>\n  <bpmndi:BPMNDiagram id="BPMNDiagram_1">\n    <bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="doc-triage-review">\n      <bpmndi:BPMNShape id="start_di" bpmnElement="start"><omgdc:Bounds x="100" y="182" width="36" height="36"/></bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="admin_triage_di" bpmnElement="admin_triage"><omgdc:Bounds x="200" y="160" width="120" height="80"/></bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="gw_route_di" bpmnElement="gw_route" isMarkerVisible="true"><omgdc:Bounds x="380" y="175" width="50" height="50"/></bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="backoffice_review_di" bpmnElement="backoffice_review"><omgdc:Bounds x="490" y="80" width="120" height="80"/></bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="reviewer_review_di" bpmnElement="reviewer_review"><omgdc:Bounds x="490" y="240" width="120" height="80"/></bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="gw_final_di" bpmnElement="gw_final" isMarkerVisible="true"><omgdc:Bounds x="680" y="255" width="50" height="50"/></bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="end_approved_di" bpmnElement="end_approved"><omgdc:Bounds x="792" y="212" width="36" height="36"/></bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="end_rejected_di" bpmnElement="end_rejected"><omgdc:Bounds x="792" y="312" width="36" height="36"/></bpmndi:BPMNShape>\n      <bpmndi:BPMNEdge id="f1_di" bpmnElement="f1"><omgdi:waypoint x="136" y="200"/><omgdi:waypoint x="200" y="200"/></bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="f2_di" bpmnElement="f2"><omgdi:waypoint x="320" y="200"/><omgdi:waypoint x="380" y="200"/></bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="f3_bo_di" bpmnElement="f3_bo"><omgdi:waypoint x="405" y="175"/><omgdi:waypoint x="405" y="120"/><omgdi:waypoint x="490" y="120"/></bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="f3_rev_di" bpmnElement="f3_rev"><omgdi:waypoint x="405" y="225"/><omgdi:waypoint x="405" y="280"/><omgdi:waypoint x="490" y="280"/></bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="f4_di" bpmnElement="f4"><omgdi:waypoint x="550" y="160"/><omgdi:waypoint x="550" y="240"/></bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="f5_di" bpmnElement="f5"><omgdi:waypoint x="610" y="280"/><omgdi:waypoint x="680" y="280"/></bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="f6_approve_di" bpmnElement="f6_approve"><omgdi:waypoint x="705" y="255"/><omgdi:waypoint x="705" y="230"/><omgdi:waypoint x="792" y="230"/></bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="f6_reject_di" bpmnElement="f6_reject"><omgdi:waypoint x="705" y="305"/><omgdi:waypoint x="705" y="330"/><omgdi:waypoint x="792" y="330"/></bpmndi:BPMNEdge>\n    </bpmndi:BPMNPlane>\n  </bpmndi:BPMNDiagram>\n</definitions>',
  'VISUAL',
  'DRAFT',
  48
);
